async function readCertification(input){const file=input.files?.[0];if(!file)return;const target=state.onboarded?state.profile:state.setup;if(!['application/pdf','image/png','image/jpeg'].includes(file.type)||file.size>2*1024*1024){toast('Choose a PDF, PNG or JPG under 2 MB.');input.value='';return}const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file)});const old=target.certification;target.certification={name:file.name,type:file.type,size:file.size,data,uploadedAt:new Date().toISOString()};if(!save()){target.certification=old;input.value='';toast('Browser storage is full. Choose a smaller certificate.');return}document.querySelector('#certification-current').innerHTML=certificateSummary(target.certification);input.required=false;toast('Certification uploaded locally.')}
function syncCustomLogo(plan){if(!plan.documentHtml)return;const doc=new DOMParser().parseFromString(plan.documentHtml,'text/html');const logo=doc.querySelector('.report-logo');if(logo){logo.style.textAlign=plan.style.logoAlign||'left';const img=logo.querySelector('img');if(img){img.src=plan.style.logo||logoUrl;img.style.maxWidth=(plan.style.logoWidth||150)+'px'}}plan.documentHtml=cleanRichText(doc.body.innerHTML)}
function runTriggers(force=false){if(!state.session||!state.onboarded)return;const actions=dueTriggers(state,new Date(),force);for(const action of actions){const {client,key}=action;let message,job;
 if(action.type==='followup')message=`Check-in overdue by ${action.overdue} days. Review this client’s progress.`;
 else if(action.type==='reminder')message='Month-end review is due. Review the questionnaire and create the next plan.';
 else{const result=automationInput(state,client);if(result.error)message='Draft not generated: '+result.error;else if(state.credits<models[state.tier].cost)message='Draft not generated: not enough credits.';else{job=startJob(result.input,client.id,{background:true});message=job?'Monthly sample draft generation started. Review it before publishing.':'Draft not generated. Please review the client.'}}
 state.automations.runs[key]={at:Date.now(),clientName:client.name,message,jobId:job?.id,status:job?'Running':action.type==='generate'?'Needs attention':'Notified'};
 state.notifications.push({id:uid('N'),clientId:client.id,title:client.name+' · '+(action.type==='followup'?'follow-up due':action.type==='generate'?'monthly draft':'month-end review'),detail:message,read:false});
 }if(actions.length){persist();if(!force)toast(actions.length+' scheduled updates added to Notifications.')}return actions.length}
setInterval(()=>runTriggers(),30000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')runTriggers()});
runTriggers();
